        if (has_preview_medias) flags_v |= (1u << 6);
        if (user_id.has_value()) flags_v |= (1u << 0);
        if (description.has_value()) flags_v |= (1u << 1);
        if (description_photo.has_value()) flags_v |= (1u << 4);
        if (description_document.has_value()) flags_v |= (1u << 5);
